}

/// A lookup for a key no row carries.
///
/// Thrown by the generated `...OrThrow` lookups, which is where a caller has said the key
/// has to be there. The `find` forms answer the same question with nil.
///
/// Its own type rather than `TcbError`: nothing is wrong with the file, and a caller
/// catching one of these is not catching the other.
public struct RecordNotFoundError: Error, CustomStringConvertible, Sendable {
    public let message: String

    public init(_ message: String) { self.message = message }

    public var description: String { message }
}

