    public static let encodingVarint: Int32 = 1
    public static let encodingDelta: Int32 = 2
    public static let encodingRle: Int32 = 3
    public static let encodingDeltaRle: Int32 = 4
    public static let encodingDict: Int32 = 5
    public static let encodingDictRle: Int32 = 6
    public static let encodingDictFront: Int32 = 7
    public static let encodingDictFrontRle: Int32 = 8

