    public static let magicOffset = 0
    public static let versionOffset = 4
    public static let flagsOffset = 8
    public static let cipherOffset = 9
    public static let nonceOffset = 10
    public static let macOffset = 22
    public static let keyCheckOffset = 38

    /// Where the body begins. The header before it is always this long.
    public static let headerSize = 42

    public static let nonceSize = 12
    public static let macSize = 16

    /// The signature, as the fixed32 it is on disk: 'S' 'C' 'B' 0, little endian.
