            }
        }

        /// A Double member from f64, f32 or i32 - all exact in a Double.
        public func readF64As(_ element: Int32) throws -> Double {
            switch element {
            case elementF64: return try readDouble()
            case elementF32: return Double(try readFloat())
            default: return Double(try readInt32())
            }
        }

        /// Bytes left to read.
        public var remaining: Int { data.count - position }

        private func take(_ count: Int) throws -> Int {
