            let start = position
            position += count

            return start
        }

        /// One byte.
        public func readUInt8() throws -> UInt8 {
            let at = try take(1)
            return data[at]
        }

        public func readBool() throws -> Bool { try readUInt8() != 0 }

        public func readInt32() throws -> Int32 {
