            let value = UInt32(data[at])
                | (UInt32(data[at + 1]) &<< 8)
                | (UInt32(data[at + 2]) &<< 16)
                | (UInt32(data[at + 3]) &<< 24)

            return Int32(bitPattern: value)
        }

        public func readInt64() throws -> Int64 {
            let at = try take(8)

            var value: UInt64 = 0
            for i in stride(from: 7, through: 0, by: -1) {
                value = (value &<< 8) | UInt64(data[at + i])
            }

            return Int64(bitPattern: value)
        }

        /// A single-precision value as its stored bit pattern, so the value survives
        /// exactly rather than through a decimal rendering.
        public func readFloat() throws -> Float {
            let bits = try readInt32()
            return Float(bitPattern: UInt32(bitPattern: bits))
        }

        public func readDouble() throws -> Double {
            let bits = try readInt64()
            return Double(bitPattern: UInt64(bitPattern: bits))
        }

        /// The next `count` bytes copied into `destination` at `at`.
