            let start = try take(count)
            for i in 0 ..< count { destination[at + i] = data[start + i] }
        }

        /// A length-prefixed UTF-8 string.
        public func readString() throws -> String {
            let length = try readCounter32()

            if length < 0 { throw TcbError("string length is negative") }
            if length == 0 { return "" }

            let at = try take(length)
            return String(decoding: data[at ..< (at + length)], as: UTF8.self)
        }

        /// A timestamp as .NET ticks: 100 ns units since 0001-01-01.
        ///
        /// Ticks rather than a Foundation Date: the conversion is lossy coming back, and a
        /// caller passing the value through should not pay for it.
