        /// A duration as .NET ticks.
        public func readDurationTicks() throws -> Int64 { try readInt64() }

        public func readUuid() throws -> Uuid {
            let at = try take(16)
            return Uuid(Array(data[at ..< (at + 16)]))
        }

        /// An int64 written in as few bytes as its magnitude needed, either sign.
        ///
        /// The base of a bit-packed block, which is a value of the column's own element
        /// type - an i64 column's base does not fit in thirty-two bits. One byte when it
        /// is zero.
        public func readCounter64() throws -> Int64 {
            var encoded: UInt64 = 0
            var shift: UInt64 = 0

            while true {
                let piece = try readUInt8()
                encoded |= (UInt64(piece) & 0x7F) &<< shift

                if piece & 0x80 == 0 { break }

                shift += 7

                if shift > 63 {
                    throw TcbError("a 64-bit variable length integer runs past ten bytes")
                }
            }

            return Int64(bitPattern: (encoded >> 1) ^ (0 &- (encoded & 1)))
        }

        /// A stream of bytes under one of the integer encodings, which is what a packed
        /// block and a presence bitmap both end in.
        ///
        /// One reader for both, so a bitmap and a packed value block cannot disagree about
        /// the same bits. The count is known before the call in both cases, so nothing
        /// here reads a length.
        public func readByteStream(
            _ encoding: Int32, _ count: Int, _ fieldName: String
        ) throws -> [UInt8] {
            var out = [UInt8](repeating: 0, count: count)

            if encoding == encodingRaw {
                for at in 0 ..< count { out[at] = try readUInt8() }

                return out
            }

            if encoding > encodingDeltaRle {
                throw TcbError(
                    "\(fieldName): encoding \(encoding) cannot carry a packed byte stream")
            }

            let walking = encoding == encodingDelta || encoding == encodingDeltaRle

            var filled = 0
            var previous: Int32 = 0

            // The first value of a delta stream is written outright; the rest are steps
            // from it. A run in a delta stream repeats the step, not the value, so it
            // walks.
            if count > 0 && walking {
                previous = try asByte(try readOptimalInt32(), fieldName)
                out[filled] = UInt8(previous)
                filled += 1
            }

            while filled < count {
                var run = 1
                var step: Int32 = 0
                var value: Int32 = 0

                switch encoding {
                case encodingVarint:
                    value = try asByte(try readOptimalInt32(), fieldName)
                case encodingDelta:
                    step = try readOptimalInt32()
                case encodingRle:
                    run = try readCounter32()
                    value = try asByte(try readOptimalInt32(), fieldName)
                default:
                    run = try readCounter32()
                    step = try readOptimalInt32()
                }

                if run < 1 || run > count - filled {
                    throw TcbError(
                        "\(fieldName): a run of \(run) cannot cover the "
                        + "\(count - filled) bytes left")
                }

                for _ in 0 ..< run {
                    if walking {
                        previous = try asByte(previous &+ step, fieldName)
                        out[filled] = UInt8(previous)
                    } else {
                        out[filled] = UInt8(value)
                    }
                    filled += 1
                }
            }

            return out
        }

        /// A decoded value that has to be a byte, or the block is corrupt.
        private func asByte(_ value: Int32, _ fieldName: String) throws -> Int32 {
            if value < 0 || value > 255 {
                throw TcbError("\(fieldName): \(value) is not a byte")
            }

            return value
        }

        /// An Int32 written in as few bytes as its magnitude needed, either sign.
        public func readOptimalInt32() throws -> Int32 {
            let encoded = try readVarint32()

            // Undoes the zig-zag fold: the low bit carried the sign. Unsigned throughout -
            // an arithmetic shift would drag the sign bit down for any value above 2^31,
            // and negating the low bit has to wrap rather than trap.
            return Int32(bitPattern: (encoded >> 1) ^ (0 &- (encoded & 1)))
        }

        /// A count, in the same encoding as `readOptimalInt32`, as the Int a length is.
        public func readCounter32() throws -> Int { Int(try readOptimalInt32()) }

        /// An enum value, which travels zig-zag encoded rather than fixed width.
        public func readEnum() throws -> Int32 { try readOptimalInt32() }

        private func readVarint32() throws -> UInt32 {
            var value: UInt32 = 0

            var shift: UInt32 = 0
            while shift < 35 {
                let b = try readUInt8()
                value |= (UInt32(b) & 0x7F) &<< shift

                if b & 0x80 == 0 { return value }

                shift += 7
            }

            throw TcbError("varint32 is longer than five bytes")
        }
    }

    /// Reads one scalar column's values in row order, whatever the block's encoding.
    ///
    /// The generated row loop stays a row loop; this is the one place that knows how a
    /// delta accumulates, how long a run has left, or that a dictionary index is a
    /// reference into strings decoded once. That last one matters beyond file size: a
    /// hundred-thousand-row column with three distinct strings allocates three strings,
    /// not a hundred thousand.
    ///
    /// checkColumn has already refused any (element, encoding) pair the spec does not
    /// define, so the branches here do not re-litigate that.
    public final class ColumnCursor {

        private let reader: Reader
        private let fieldName: String
        private let element: Int32

        // Reassigned by the compositions: an array block, a whole-number block and a
        // segment dictionary each name the encoding the stream under them is really in,
        // and rewriting this is what lets every path below go on knowing only the nine
        // layouts.
        private var encoding: Int32

        // A run-length family's current run: what remains of it, and its value - which is
        // a plain value for RLE, a delta for DELTA_RLE, an index for DICT_RLE.
        private var runRemaining = 0
        private var runValue: Int32 = 0

        // The delta family's accumulator, once started.
        private var previous: Int32 = 0
        private var started = false

        // Values not yet handed out. A run that claims more than this is corrupt, and
        // catching it here names the field instead of leaving it to the block-end check.
        // For an array column this counts elements, not rows.
        private var rowsRemaining: Int

        /// How many elements each row holds, decoded up front for an encoded array column.
        ///
        /// Up front because the element stream follows the length stream in the block, so
        /// every length has been read by the time the first element is. Nil for a raw
        /// array, whose lengths are interleaved with its elements and read as they are
        /// reached.
        private var lengths: [Int]?

        private var lengthAt = 0

        /// Whether a float column's values are travelling as integers.
        private var wholeNumbers = false

        /// A bit-packed column's bytes, decoded up front, and where in them the next value
        /// is.
        ///
        /// Up front because the bytes are themselves under an encoding and a value can
        /// cross a byte boundary, so handing values out one at a time would mean carrying
        /// a decoder and a bit offset that disagree about where they are.
        private var packed: [UInt8] = []
        private var packedWidth = 0
        private var packedBase: Int64 = 0
        private var packedBit = 0

        /// The block's dictionary, decoded once and handed out per row.
        ///
        /// One of these is filled when the block has a dictionary at all, chosen by the
        /// element: strings are decoded to instances that rows then share, and a
        /// fixed-width element keeps its raw bytes so the value is reconstructed exactly
        /// as the raw layout would have read it. `valueWidth` being non-zero is what says
        /// the block's dictionary is the second kind.
        private var dictionary: [String] = []

        private var valueDictionary: [UInt8] = []
        private var valueWidth = 0

        /// The value the last `nextSameI32` decoded.
        public var runSameValue: Int32 = 0

        /// The string the last `nextSameString` decoded.
        public var runSameText: String = ""

        public init(
            _ reader: Reader, _ column: Column, _ rowCount: Int, _ fieldName: String
        ) throws {
            self.reader = reader
            self.fieldName = fieldName
            self.element = column.element
            self.encoding = column.encoding
            self.rowsRemaining = rowCount

            // An array column's block names an encoding for its elements and, where its
            // rows differ in length, one for the lengths. Both are encodings that already
            // exist, so all this does is read them and then go on being the element
            // stream's cursor.
            if encoding == encodingArray {
                encoding = Int32(try reader.readUInt8())

                if column.kind == kindArray {
                    let lengthEncoding = Int32(try reader.readUInt8())
                    let rowLengths = try Tcb.readLengths(
                        reader, lengthEncoding, rowCount, fieldName)

                    var elements: Int64 = 0
                    for length in rowLengths { elements += Int64(length) }

                    if elements > Int64(Int32.max) {
                        throw TcbError(
                            "\(fieldName): the column declares more elements than can be held")
                    }

                    lengths = rowLengths
                    rowsRemaining = Int(elements)
                }
            }

            // A bit-packed column states the width its range needs, the base subtracted
            // from every value, and which encoding carries the packed bytes. Decoded here
            // so that handing values out is a shift and an add.
            if encoding == encodingBitpack {
                let width = Int(try reader.readUInt8())
                let base = try reader.readCounter64()
                let inner = Int32(try reader.readUInt8())

                if width < 1 || width > 64 {
                    throw TcbError(
                        "\(fieldName): a bit width of \(width) is not between 1 and 64")
                }

                packedWidth = width
                packedBase = base

                let bits = Int64(rowsRemaining) * Int64(width)

                if (bits + 7) / 8 > Int64(Int32.max) {
                    throw TcbError(
                        "\(fieldName): the packed stream is larger than can be held")
                }

                packed = try reader.readByteStream(inner, Int((bits + 7) / 8), fieldName)

                // No early exit: the dictionary sections below test for their own
                // encodings and a packed block matches none of them, so falling through
                // leaves them empty.
            }

            // A float column whose values are all whole numbers carries them as integers
            // and says which integer encoding they travel under. From here down it is that
            // encoding's cursor, and only the handing out converts back.
            if encoding == encodingWhole {
                let inner = Int32(try reader.readUInt8())

                if inner < encodingVarint || inner > encodingDeltaRle {
                    throw TcbError(
                        "\(fieldName): encoding \(inner) cannot carry a whole-number "
                        + "column's values")
                }

                encoding = inner
                wholeNumbers = true
            }

            // A segment dictionary is built once, here, and from then on the block is a
            // dictionary with an index stream like any other - so the row-by-row paths
            // below need to know nothing about it.
            let segmentDictionary =
                encoding == encodingDictSegment || encoding == encodingDictSegmentRle

            if segmentDictionary {
                dictionary = try Tcb.readSegmentDictionary(reader, fieldName)

                encoding = encoding == encodingDictSegment ? encodingDict : encodingDictRle
            }

            let plainDictionary = encoding == encodingDict || encoding == encodingDictRle

            let frontDictionary =
                encoding == encodingDictFront || encoding == encodingDictFrontRle

            if !segmentDictionary && (plainDictionary || frontDictionary) {
                let count = try reader.readCounter32()
                if count < 0 {
                    throw TcbError("\(fieldName): the dictionary entry count is negative")
                }

                if frontDictionary {
                    dictionary = try Tcb.readFrontCodedDictionary(reader, count, fieldName)
                } else if element == elementString {
                    var entries = [String]()
                    entries.reserveCapacity(count)
                    for _ in 0 ..< count { entries.append(try reader.readString()) }
                    dictionary = entries
                } else {
                    // A fixed-width element: the entries are the value's own bytes, so
                    // they are taken as bytes and turned into values only when a row asks
                    // for one.
                    valueWidth = element == elementF32 ? 4 : 8
                    valueDictionary = [UInt8](repeating: 0, count: count * valueWidth)

                    for at in 0 ..< count {
                        try reader.readBytesInto(
                            &valueDictionary, at * valueWidth, valueWidth)
                    }
                }
            }
        }

        /// How many elements the next row of an array column holds.
        ///
        /// One call whichever way the block is laid out. An encoded array decoded every
        /// length before the first element was read, so this hands out what it already
        /// has; a raw one states each row's length in front of that row's elements, so
        /// this reads it where it stands.
        public func nextLength() throws -> Int {
            if let decoded = lengths {
                if lengthAt >= decoded.count {
                    throw TcbError("\(fieldName): the column has no more rows to read")
                }

                let length = decoded[lengthAt]
                lengthAt += 1

                return length
            }

            let length = try reader.readCounter32()

            if length < 0 {
                throw TcbError("\(fieldName): a row declares \(length) elements")
            }

            return length
        }

        /// The next value of a bit-packed stream: the packed bits, over the block's base.
        ///
        /// A value may cross a byte boundary, so this walks bits rather than bytes. The
        /// addition wraps, mirroring the writer's wrapping subtraction.
        private func nextPacked() -> Int64 {
            var slot: UInt64 = 0

            for at in 0 ..< packedWidth {
                if (packed[packedBit >> 3] &>> UInt8(packedBit & 7)) & 1 != 0 {
                    slot |= (1 as UInt64) &<< UInt64(at)
                }

                packedBit += 1
            }

            return packedBase &+ Int64(bitPattern: slot)
        }

        /// The next Int32 - which also serves enums, and reference indexes.
        public func nextI32() throws -> Int32 {
            rowsRemaining -= 1

            if encoding == encodingBitpack { return Int32(truncatingIfNeeded: nextPacked()) }

            switch encoding {
            case encodingRaw:
                if element == elementI32 { return try reader.readInt32() }
                return try reader.readOptimalInt32()

            case encodingVarint:
                return try reader.readOptimalInt32()

            case encodingDelta:
                // The addition wraps on purpose, mirroring the writer's wrapping
                // subtraction; together they are exact for every Int32 pair.
                if started {
                    previous = previous &+ (try reader.readOptimalInt32())
                } else {
                    previous = try reader.readOptimalInt32()
                    started = true
                }

                return previous

            case encodingRle:
                if runRemaining == 0 { try readRun() }

                runRemaining -= 1
                return runValue

            default: // encodingDeltaRle; checkColumn refused everything else.
                if !started {
                    previous = try reader.readOptimalInt32()
                    started = true
                } else {
                    if runRemaining == 0 { try readRun() }

                    runRemaining -= 1
                    previous = previous &+ runValue
                }

                return previous
            }
        }

        /// An Int64 member: from an i64 column raw or through its dictionary, and from
        /// anything narrower by decoding an Int32 and widening it.
        public func nextI64() throws -> Int64 {
            if element != elementI64 { return Int64(try nextI32()) }

            if encoding == encodingBitpack {
                rowsRemaining -= 1

                return nextPacked()
            }

            if valueWidth != 0 { return int64At(try nextValueEntry()) }

            rowsRemaining -= 1

            return try reader.readInt64()
        }

        /// A Float member: raw, the dictionary entry's exact bit pattern, or a whole
        /// number.
        public func nextF32() throws -> Float {
            if wholeNumbers { return Float(try nextI32()) }

            if valueWidth != 0 {
                let bits = int32At(try nextValueEntry())
                return Float(bitPattern: UInt32(bitPattern: bits))
            }

            rowsRemaining -= 1

            return try reader.readFloat()
        }

        /// A Double member: from f64 or f32 - either of them raw or dictionary-encoded -
        /// and from an i32 column by decoding and widening.
        public func nextF64() throws -> Double {
            if wholeNumbers { return Double(try nextI32()) }

            switch element {
            case elementF64:
                if valueWidth != 0 {
                    let bits = int64At(try nextValueEntry())
                    return Double(bitPattern: UInt64(bitPattern: bits))
                }

                rowsRemaining -= 1
                return try reader.readDouble()

            case elementF32:
                return Double(try nextF32())

            default:
                return Double(try nextI32())
            }
        }

        /// A Bool member: one byte raw, or a run of them.
        public func nextBool() throws -> Bool {
            if encoding == encodingRle || encoding == encodingBitpack {
                return try nextI32() != 0
            }

            rowsRemaining -= 1

            return try reader.readBool()
        }

        /// The next string - the dictionary's instance where the block has one.
        public func nextString() throws -> String {
            rowsRemaining -= 1

            switch encoding {
            case encodingRaw:
                return try reader.readString()

            case encodingDict, encodingDictFront:
                let index = try reader.readCounter32()
                return try dictionaryEntry(Int32(index))

            default: // encodingDictRle and encodingDictFrontRle
                if runRemaining == 0 { try readRun() }

                runRemaining -= 1
                return try dictionaryEntry(runValue)
            }
        }

        /// Where the next row's dictionary entry starts, for a fixed-width element: an
        /// offset into the raw entries rather than a value, so the caller reads it as its
        /// own type.
        private func nextValueEntry() throws -> Int {
            rowsRemaining -= 1

            var index: Int

            if encoding == encodingDict {
                index = try reader.readCounter32()
            } else {
                if runRemaining == 0 { try readRun() }

                runRemaining -= 1
                index = Int(runValue)
            }

            let count = valueDictionary.count / valueWidth

            if index < 0 || index >= count {
                throw TcbError(
                    "\(fieldName): dictionary index \(index) is out of range - the "
                    + "dictionary holds \(count) entries")
            }

            return index * valueWidth
        }

        /// The four bytes of a dictionary entry, little endian, as the raw layout has them.
        private func int32At(_ at: Int) -> Int32 {
            let value = UInt32(valueDictionary[at])
                | (UInt32(valueDictionary[at + 1]) &<< 8)
                | (UInt32(valueDictionary[at + 2]) &<< 16)
                | (UInt32(valueDictionary[at + 3]) &<< 24)

            return Int32(bitPattern: value)
        }

        /// The eight bytes of a dictionary entry, little endian.
        private func int64At(_ at: Int) -> Int64 {
            var value: UInt64 = 0

            for i in stride(from: 7, through: 0, by: -1) {
                value = (value &<< 8) | UInt64(valueDictionary[at + i])
            }

            return Int64(bitPattern: value)
        }

        /// Up to `limit` rows that all hold the next value. The count is returned and the
        /// value is left in `runSameValue`; the count is always at least 1.
        ///
        /// This is what makes a run cost one call instead of one per row: the generated
        /// loop asks once, then assigns the value that many times. An encoding that cannot
        /// promise sameness cheaply answers 1, so the caller's loop is correct over every
        /// encoding and only faster over runs.
        ///
        /// The value comes back in a property rather than a tuple, because a tuple holding
        /// a string would be one allocation per run - and a run-length encoded column is
        /// mostly runs.
        public func nextSameI32(_ limit: Int) throws -> Int {
            if encoding == encodingRle {
                rowsRemaining -= 1
                if runRemaining == 0 { try readRun() }

                let n = runRemaining < limit ? runRemaining : limit
                runRemaining -= n
                rowsRemaining -= n - 1
                runSameValue = runValue

                return n
            }

            if encoding == encodingDeltaRle && started {
                rowsRemaining -= 1
                if runRemaining == 0 { try readRun() }

                if runValue == 0 {
                    // A zero-delta run is a run of one value.
                    let n = runRemaining < limit ? runRemaining : limit
                    runRemaining -= n
                    rowsRemaining -= n - 1
                    runSameValue = previous

                    return n
                }

                runRemaining -= 1
                previous = previous &+ runValue
                runSameValue = previous

                return 1
            }

            runSameValue = try nextI32()
            return 1
        }

        /// The string counterpart of `nextSameI32`, leaving its value in `runSameText`.
        public func nextSameString(_ limit: Int) throws -> Int {
            if encoding == encodingDictRle || encoding == encodingDictFrontRle {
                rowsRemaining -= 1
                if runRemaining == 0 { try readRun() }

                let n = runRemaining < limit ? runRemaining : limit
                runRemaining -= n
                rowsRemaining -= n - 1
                runSameText = try dictionaryEntry(runValue)

                return n
            }

            runSameText = try nextString()
            return 1
        }

        private func readRun() throws {
            let length = try reader.readCounter32()

            // + 1 because the row this run was read for is already counted out of
            // rowsRemaining by its next* call.
            if length < 1 || length > rowsRemaining + 1 {
                throw TcbError(
                    "\(fieldName): a run of \(length) values cannot cover the "
                    + "\(rowsRemaining + 1) rows left in the column")
            }

            runRemaining = length
            runValue = try reader.readOptimalInt32()
        }

        private func dictionaryEntry(_ index: Int32) throws -> String {
            if index < 0 || Int(index) >= dictionary.count {
                throw TcbError(
                    "\(fieldName): dictionary index \(index) is out of range - the "
                    + "dictionary holds \(dictionary.count) entries")
            }

            return dictionary[Int(index)]
        }
    }

    /// A sorted dictionary whose entries state only what they do not share with the entry
    /// before them.
    ///
    /// Decoded into whole strings here rather than kept folded, because a row wants a
    /// string and the folding was only ever about the bytes on disk. The scratch buffer
    /// grows to the longest entry and is reused, so the allocations are the strings
    /// themselves - one per distinct value, which is the point.
    fileprivate static func readFrontCodedDictionary(
        _ reader: Reader, _ count: Int, _ fieldName: String
    ) throws -> [String] {
        var scratch = [UInt8](repeating: 0, count: 64)
        var previousLength = 0

        var entries = [String]()
        entries.reserveCapacity(count)

        for at in 0 ..< count {
            let shared = try reader.readCounter32()
            let rest = try reader.readCounter32()

            if shared < 0 || rest < 0 || shared > previousLength {
                throw TcbError(
                    "\(fieldName): dictionary entry \(at) shares \(shared) bytes with an "
                    + "entry of \(previousLength)")
            }

            let length = shared + rest

            if length > scratch.count {
                var capacity = scratch.count
                while capacity < length { capacity *= 2 }

                // Grown rather than replaced: the shared bytes of this entry are already
                // in there, left by the entry before it.
                scratch.append(
                    contentsOf: [UInt8](repeating: 0, count: capacity - scratch.count))
            }

            if rest > 0 { try reader.readBytesInto(&scratch, shared, rest) }

            previousLength = length

            entries.append(
                length == 0 ? "" : String(decoding: scratch[0 ..< length], as: UTF8.self))
        }

        return entries
    }

    /// The lengths of an array column's rows, as their own encoded stream.
    ///
    /// A varint stream, so what may be chosen for it is what may be chosen for any varint
    /// column - each length as a counter32, or runs of them. Most columns have rows that
    /// are all the same length, which is one run.
    fileprivate static func readLengths(
        _ reader: Reader, _ encoding: Int32, _ rowCount: Int, _ fieldName: String
    ) throws -> [Int] {
        var lengths = [Int](repeating: 0, count: rowCount)

        if encoding == encodingRaw {
            for at in 0 ..< rowCount {
                lengths[at] = try reader.readCounter32()

                if lengths[at] < 0 {
                    throw TcbError(
                        "\(fieldName): row \(at) declares \(lengths[at]) elements")
                }
            }

            return lengths
        }

        if encoding != encodingRle {
            throw TcbError(
                "\(fieldName): encoding \(encoding) cannot carry an array column's row "
                + "lengths")
        }

        var filled = 0

        while filled < rowCount {
            let run = try reader.readCounter32()
            let value = try reader.readCounter32()

            if run < 1 || run > rowCount - filled {
                throw TcbError(
                    "\(fieldName): a run of \(run) lengths cannot cover the "
                    + "\(rowCount - filled) rows left in the column")
            }

            if value < 0 {
                throw TcbError("\(fieldName): a row declares \(value) elements")
            }

            for _ in 0 ..< run {
                lengths[filled] = value
                filled += 1
            }
        }

        return lengths
    }

    /// A dictionary whose entries are lists of references into a table of the pieces they
    /// are built from.
    ///
    /// Two reads and a concatenation: the table, which is front coded because its own
    /// entries share their fronts, and then each value as the pieces it is made of. The
    /// result is the same array of whole strings every other dictionary produces, so
    /// nothing downstream of here knows which kind it came from.
    fileprivate static func readSegmentDictionary(
        _ reader: Reader, _ fieldName: String
    ) throws -> [String] {
        let segmentCount = try reader.readCounter32()

        if segmentCount < 0 {
            throw TcbError("\(fieldName): the segment count is negative")
        }

        if segmentCount > reader.remaining {
            throw TcbError(
                "\(fieldName): a segment table of \(segmentCount) entries is larger than "
                + "the file can hold")
        }

        var segments = [[UInt8]]()
        segments.reserveCapacity(segmentCount)
        var previousLength = 0

        for at in 0 ..< segmentCount {
            let shared = try reader.readCounter32()
            let rest = try reader.readCounter32()

            if shared < 0 || rest < 0 || shared > previousLength {
                throw TcbError(
                    "\(fieldName): segment \(at) shares \(shared) bytes with an entry of "
                    + "\(previousLength)")
            }

            var segment = [UInt8](repeating: 0, count: shared + rest)

            if shared > 0 {
                for i in 0 ..< shared { segment[i] = segments[at - 1][i] }
            }
            if rest > 0 { try reader.readBytesInto(&segment, shared, rest) }

            segments.append(segment)
            previousLength = segment.count
        }

        let count = try reader.readCounter32()

        if count < 0 {
            throw TcbError("\(fieldName): the dictionary entry count is negative")
        }

        if count > reader.remaining {
            throw TcbError(
                "\(fieldName): a dictionary of \(count) entries is larger than the file "
                + "can hold")
        }

        var scratch = [UInt8](repeating: 0, count: 64)

        var entries = [String]()
        entries.reserveCapacity(count)

        for at in 0 ..< count {
            let pieces = try reader.readCounter32()

            if pieces < 0 {
                throw TcbError(
                    "\(fieldName): dictionary entry \(at) declares \(pieces) pieces")
            }

            var length = 0

            for _ in 0 ..< pieces {
                let index = try reader.readCounter32()

                if index < 0 || index >= segmentCount {
                    throw TcbError(
                        "\(fieldName): segment index \(index) is out of range - the table "
                        + "holds \(segmentCount) entries")
                }

                let segment = segments[index]

                if length + segment.count > scratch.count {
                    var capacity = scratch.count
                    while capacity < length + segment.count { capacity *= 2 }

                    scratch.append(
                        contentsOf: [UInt8](repeating: 0, count: capacity - scratch.count))
                }

                for i in 0 ..< segment.count { scratch[length + i] = segment[i] }
                length += segment.count
            }

            entries.append(
                length == 0 ? "" : String(decoding: scratch[0 ..< length], as: UTF8.self))
        }

        return entries
    }

    /// A file's plaintext bytes, checked against its MAC on the way.
    ///
    /// Call this on the bytes before handing them to a reader. A file that is neither
    /// encrypted nor authenticated comes back untouched, so the call belongs in the load
    /// path whether or not the project uses either.
    ///
    /// The order is verify, then decrypt. The tag covers the file as it is stored, so an
    /// altered file is refused before the key is used on it, and the header - the flags,
    /// the cipher byte, the nonce - is covered along with the body.
    ///
    /// An encrypted file is decrypted into one new array of the same length rather than in
    /// place, because the header has to survive the decryption. The fields the envelope
    /// wrote are returned to what a plain file holds in them.
    ///
    /// What the two layers are and are not for: both keys ship inside the client that
    /// reads the file. Encryption stops a data file being read in an editor; the MAC stops
    /// an edited one loading. Neither stops anyone who can take the keys out of the
    /// client, and no format does.
    ///
    /// `macKey` is nil when the project does not sign its files. A reader that has one
    /// refuses a file that carries no MAC: the field being zero is how a file says it is
    /// unauthenticated, so accepting that from a project that signs its files would put
    /// the check sixteen zero bytes away from being removed.
    ///
    /// `verifyMac` false skips the check. For tools and for measuring load time - and no
    /// weaker than it looks, because anyone who can flip this flag in a shipped binary can
    /// read the key out of the same binary.
    ///
    /// Named `openTable` rather than `open`: a global `open` would sit beside the POSIX
    /// one that Foundation already brings in.
    public static func openTable(
        _ data: [UInt8],
        key: [UInt8]?,
        macKey: [UInt8]? = nil,
        verifyMac: Bool = true
    ) throws -> [UInt8] {
        if data.count < headerSize {
            throw TcbError("the file is too short to be a table")
        }

        if readMagic(data, magicOffset) != magic {
            throw TcbError("the file does not begin with the table file signature")
        }

        if verifyMac { try checkMac(data, macKey) }

        if data[flagsOffset] & flagEncrypted == 0 { return data }

        let cipher = data[cipherOffset]

        if cipher != cipherChaCha20 {
            throw TcbError(
                "the file uses cipher \(cipher), which this reader does not know")
        }

        guard let key = key, key.count == 32 else {
            throw TcbError(
                "the file is encrypted and no key, or a key that is not 32 bytes, was given")
        }

        var plain = data

        // The stream cipher of RFC 8439 rather than the authenticated construction, so
        // applying it leaves every byte count as it was and the structural checks hold
        // over the ciphertext unchanged. Written out here because neither CryptoKit nor
        // swift-crypto exposes a bare ChaCha20 - both offer only ChaChaPoly, whose nonce
        // and tag are a different construction. spec/tcb-v104-composed-encodings.md.
        chaCha20Apply(key, &plain, nonceOffset, keyCheckOffset)

        if readMagic(plain, keyCheckOffset) != magic {
            throw TcbError(
                "the file did not decrypt to a table - the key is not the one it was "
                + "written with")
        }

        // Back to what a plain file holds in these bytes, so that a second call over what
        // this returns passes it through instead of decrypting it again.
        plain[flagsOffset] = plain[flagsOffset] & ~flagEncrypted
        plain[cipherOffset] = cipherNone

        for at in 0 ..< nonceSize { plain[nonceOffset + at] = 0 }

        return plain
    }

    /// Four bytes as the fixed32 the signature and the key check are compared as.
    private static func readMagic(_ data: [UInt8], _ at: Int) -> Int32 {
        let value = UInt32(data[at])
            | (UInt32(data[at + 1]) &<< 8)
            | (UInt32(data[at + 2]) &<< 16)
            | (UInt32(data[at + 3]) &<< 24)

        return Int32(bitPattern: value)
    }

    /// The MAC field against the file's own bytes, and against whether a key was given.
    ///
    /// The tag is HMAC-SHA-256 over every byte but the sixteen it lives in, truncated to
    /// those sixteen. From the platform, unlike the cipher: HMAC-SHA-256 reaches the CPU's
    /// SHA extensions through CryptoKit or swift-crypto, and a hand-written one does not.
    /// spec/tcb-mac-and-signature.md has the measurement that decided it.
    ///
    /// What it catches is what the structural checks cannot. A block length that does not
    /// add up is a malformed file and the reader says so; four other bytes in an f32 column
    /// is a well-formed file holding a different number, and no check over a file's shape
    /// can tell that from data that was always there.
    private static func checkMac(_ data: [UInt8], _ macKey: [UInt8]?) throws {
        // Nothing to check with. A file that carries a tag is read anyway rather than
        // refused: this reader has no way to tell whether the tag is good, and a client
        // built before the project turned MACs on is one this format has promised can
        // still read what it is sent.
        guard let macKey = macKey, !macKey.isEmpty else { return }

        if macKey.count != 32 { throw TcbError("the MAC key given is not 32 bytes") }

        var present = false

        for at in 0 ..< macSize where data[macOffset + at] != 0 {
            present = true
            break
        }

        if !present {
            throw TcbError(
                "the file carries no MAC and this build expects one - it was exported "
                + "without a MAC key, or the field was cleared after it was written")
        }

        #if canImport(CryptoKit) || canImport(Crypto)
        var tag = HMAC<SHA256>(key: SymmetricKey(data: macKey))

        // Two updates: the sixteen bytes the tag lives in cannot be part of what produces
        // it. Skipping them is zeroing them without copying the file.
        tag.update(data: data[0 ..< macOffset])
        tag.update(data: data[keyCheckOffset ..< data.count])

        let expected = Array(tag.finalize())

        // Every byte, always: a comparison that returns early tells the caller how far it
        // got.
        var difference: UInt8 = 0

        for at in 0 ..< macSize {
            difference |= expected[at] ^ data[macOffset + at]
        }

        if difference != 0 {
            throw TcbError(
                "the file does not match its MAC - it was altered after it was exported, "
                + "or it was signed with a different key")
        }
        #else
        // Neither CryptoKit nor swift-crypto is in this build. The reader still reads
        // every file; what it cannot do is tell a good tag from a bad one, and reporting
        // that beats reporting nothing. spec/swift-language-support.md.
        throw TcbError(
            "this file carries a MAC and verifying one needs a SHA-256 implementation, "
            + "which this build has none of - add the swift-crypto package "
            + "(https://github.com/apple/swift-crypto) to the target, or pass "
            + "verifyMac: false to read without the check")
        #endif
    }

    // The ChaCha20 stream cipher of RFC 8439, as the file envelope uses it: a 256-bit key,
    // a 96-bit nonce, and a block counter that starts at zero.

    private static func quarterRound(
        _ x: inout [UInt32], _ a: Int, _ b: Int, _ c: Int, _ d: Int
    ) {
        x[a] = x[a] &+ x[b]; x[d] = rotate(x[d] ^ x[a], 16)
        x[c] = x[c] &+ x[d]; x[b] = rotate(x[b] ^ x[c], 12)
        x[a] = x[a] &+ x[b]; x[d] = rotate(x[d] ^ x[a], 8)
        x[c] = x[c] &+ x[d]; x[b] = rotate(x[b] ^ x[c], 7)
    }

    private static func rotate(_ value: UInt32, _ by: UInt32) -> UInt32 {
        (value &<< by) | (value &>> (32 &- by))
    }

    /// XORs the keystream over `data` from `from` to its end, in place.
    private static func chaCha20Apply(
        _ key: [UInt8], _ data: inout [UInt8], _ nonceAt: Int, _ from: Int
    ) {
        var state = [UInt32](repeating: 0, count: 16)

        // "expand 32-byte k", the constant the state begins with.
        state[0] = 0x6170_7865
        state[1] = 0x3320_646E
        state[2] = 0x7962_2D32
        state[3] = 0x6B20_6574

        for at in 0 ..< 8 {
            state[4 + at] = UInt32(key[at * 4])
                | (UInt32(key[at * 4 + 1]) &<< 8)
                | (UInt32(key[at * 4 + 2]) &<< 16)
                | (UInt32(key[at * 4 + 3]) &<< 24)
        }

        for at in 0 ..< 3 {
            state[13 + at] = UInt32(data[nonceAt + at * 4])
                | (UInt32(data[nonceAt + at * 4 + 1]) &<< 8)
                | (UInt32(data[nonceAt + at * 4 + 2]) &<< 16)
                | (UInt32(data[nonceAt + at * 4 + 3]) &<< 24)
        }

        var counter: UInt32 = 0
        var at = from

        var working = [UInt32](repeating: 0, count: 16)
        var block = [UInt8](repeating: 0, count: 64)

        while at < data.count {
            state[12] = counter

            for i in 0 ..< 16 { working[i] = state[i] }

            // Twenty rounds as ten double rounds: four columns, then four diagonals.
            for _ in 0 ..< 10 {
                quarterRound(&working, 0, 4, 8, 12)
                quarterRound(&working, 1, 5, 9, 13)
                quarterRound(&working, 2, 6, 10, 14)
                quarterRound(&working, 3, 7, 11, 15)
                quarterRound(&working, 0, 5, 10, 15)
                quarterRound(&working, 1, 6, 11, 12)
                quarterRound(&working, 2, 7, 8, 13)
                quarterRound(&working, 3, 4, 9, 14)
            }

            for i in 0 ..< 16 {
                let word = working[i] &+ state[i]

                block[i * 4] = UInt8(truncatingIfNeeded: word)
                block[i * 4 + 1] = UInt8(truncatingIfNeeded: word &>> 8)
                block[i * 4 + 2] = UInt8(truncatingIfNeeded: word &>> 16)
                block[i * 4 + 3] = UInt8(truncatingIfNeeded: word &>> 24)
            }

            var taken = 0
            while taken < 64 && at < data.count {
                data[at] = data[at] ^ block[taken]
                taken += 1
                at += 1
            }

            counter = counter &+ 1
        }
    }

    /// Reads and checks a table file's header, returning the row count that follows it.
    ///
    /// Every bit of the flags byte is refused, the sealed one included: `openTable` clears
    /// it on the plaintext it hands back, so a reader still meeting it was given the
    /// ciphertext without the key, and saying that beats letting the block lengths make
    /// what they can of it. Any other bit means the file needs handling this build does
    /// not have.
    public static func readTableHeader(_ reader: Reader) throws -> Header {
        // Checked again here rather than only in openTable, because a reader can be handed
        // bytes that never went through it.
        if try reader.readInt32() != magic {
            throw TcbError("the file does not begin with the table file signature")
        }

        let version = try reader.readInt32()

        if version != formatVersion {
            throw TcbError(
                "table format version \(UInt32(bitPattern: version)) is not supported "
                + "(expected \(formatVersion))")
        }

        let flags = try reader.readUInt8()

        if flags & flagEncrypted != 0 {
            throw TcbError(
                "the table is encrypted and was not decrypted - pass the key through "
                + "openTable first")
        }

        if flags != 0 { throw TcbError("table declares unsupported features") }

        // The cipher byte, the nonce, the MAC and the key check. openTable has dealt with
        // all four by now; what is left is to be standing at the body.
        try reader.skip(headerSize - cipherOffset)

        let count = try reader.readCounter32()
        if count < 0 { throw TcbError("table row count is negative") }

        let columnCount = try reader.readCounter32()
        if columnCount < 0 { throw TcbError("table column count is negative") }

        var columns = [Column]()
        columns.reserveCapacity(columnCount)

        for _ in 0 ..< columnCount {
            let tag = try reader.readCounter32()
            let wire = Int32(try reader.readUInt8())
            let encoding = Int32(try reader.readUInt8())
            let byteLength = Int(try reader.readInt32())

            columns.append(
                Column(
                    tag: Int32(tag),
                    element: wire & 0x0F,
                    kind: (wire >> 4) & 0x03,
                    encoding: encoding,
                    byteLength: byteLength,
                    nullable: (wire & 0x40) != 0,
                    elementNullable: (wire & 0x80) != 0))
        }

        // What the descriptors say about the file, checked before anybody allocates for
        // the row count. The blocks are all that follows the header, so their declared
        // lengths have to add up to the bytes left. A raw block also costs at least one
        // byte per row - a varint's shortest form, an empty string's length prefix, a
        // variable array's counter - so a larger row count is one the exporter could not
        // have written. An encoded block has no such floor; its decode checks run sums and
        // dictionary bounds instead.

        let available = reader.remaining
        var declared = 0

        for column in columns {
            if column.byteLength < 0 || column.byteLength > available - declared {
                throw TcbError(
                    "column tag \(column.tag) declares \(column.byteLength) bytes, which "
                    + "the file cannot hold")
            }

            declared += column.byteLength

            if column.encoding == encodingRaw && count > column.byteLength {
                throw TcbError(
                    "the row count \(count) is larger than column tag \(column.tag) can "
                    + "hold in its \(column.byteLength) bytes")
            }
        }

        if declared != available {
            throw TcbError(
                "the columns declare \(declared) bytes but \(available) follow the header")
        }

        return Header(rowCount: count, columns: columns)
    }

    /// A column's element bitmap, which sits behind the row bitmap and in front of the
    /// values.
    ///
    /// Empty for a column that does not carry one. Its length is written ahead of it as a
    /// counter32, because a variable-length column's total is the sum of its row lengths
    /// and those live inside the value block - a reader meeting the bitmap first would
    /// have nothing to size it by. spec/nullable-array-elements.md.
    public static func readElementPresence(
        _ reader: Reader, _ column: Column
    ) throws -> [UInt8] {
        if !column.elementNullable { return [] }

        let elements = try reader.readCounter32()
        let encoding = Int32(try reader.readUInt8())

        return try reader.readByteStream(
            encoding, (elements + 7) / 8, "an element presence bitmap")
    }

    /// A nullable column's presence bitmap, which sits at the front of its block.
    ///
    /// Empty for a column that is not optional, which is what lets the generated code call
    /// `isPresent` without testing first.
    public static func readPresence(
        _ reader: Reader, _ column: Column, _ rowCount: Int
    ) throws -> [UInt8] {
        if !column.nullable { return [] }

        // The bitmap is a bit-packed boolean column of width one, so it carries an
        // encoding byte and is laid out by the same choice a packed value block uses. Its
        // width and base are known in advance, which is why it does not carry them.
        let encoding = Int32(try reader.readUInt8())

        return try reader.readByteStream(encoding, (rowCount + 7) / 8, "a presence bitmap")
    }

    /// Whether a row has a value, for a column that says which do.
    ///
    /// An empty bitmap means the column is not optional, and then every row has one.
    public static func isPresent(_ presence: [UInt8], _ row: Int) -> Bool {
        presence.isEmpty || (presence[row >> 3] & (1 &<< UInt8(row & 7))) != 0
    }

    /// That a column is what the generated member expects, or a lossless promotion of it.
    /// Refusal is by name and both types, never by reading anyway.
    public static func checkColumn(
        _ column: Column, _ fieldName: String, _ kind: Int32,
        _ nullable: Bool, _ accepted: Int32...
    ) throws {
        try checkColumnCore(
            column, fieldName, kind, nullable, false, accepted)
    }

    /// The same, for a member whose array elements may be absent.
    public static func checkColumnWithElements(
        _ column: Column, _ fieldName: String, _ kind: Int32,
        _ nullable: Bool, _ accepted: Int32...
    ) throws {
        try checkColumnCore(
            column, fieldName, kind, nullable, true, accepted)
    }

    private static func checkColumnCore(
        _ column: Column, _ fieldName: String, _ kind: Int32,
        _ nullable: Bool, _ elementNullable: Bool, _ accepted: [Int32]
    ) throws {
        // The same statement about the other bitmap: code not expecting one would read it
        // as values. spec/nullable-array-elements.md.
        if column.elementNullable != elementNullable {
            throw TcbError(
                "\(fieldName): the file and the generated member disagree about whether "
                + "this column's elements are optional. The schema changed; regenerate "
                + "the code or rebuild the data.")
        }

        // Nullability is part of the shape: a file that says optional puts a presence
        // bitmap in front of the block, and code not expecting one would read the bitmap
        // as values. So adding or removing a `?` is a schema change like any other, caught
        // here rather than in whatever the misread bytes happened to mean.
        if column.nullable != nullable {
            throw TcbError(
                "\(fieldName): the file and the generated member disagree about whether "
                + "this column is optional. The schema changed; regenerate the code or "
                + "rebuild the data.")
        }

        // A negative count says the member claims no length: how many elements a row holds
        // is what the file states. The kind is still the member's claim.
        // spec/nullable-array-elements.md.
        if column.kind != kind
 {
            throw TcbError(
                "\(fieldName): the file column (kind \(column.kind)) does not match "
                + "the generated member (kind \(kind)). The schema changed shape; "
                + "regenerate the code or rebuild the data.")
        }

        // An encoding this build cannot decode - or one the spec does not define for this
        // element - is refused by name, exactly like an element it cannot read. An unknown
        // column's encoding never gets here - a skip is a skip whatever the block's
        // layout.
        if !encodingSupported(column) {
            throw TcbError(
                "\(fieldName): the file's column uses encoding \(column.encoding), which "
                + "this reader cannot decode for its element type. Regenerate the code or "
                + "rebuild the data.")
        }

        if !accepted.contains(column.element) {
            let list = accepted.map { String($0) }.joined(separator: ", ")

            throw TcbError(
                "\(fieldName): the file carries element type \(column.element), which "
                + "this member cannot read (accepts \(list)). The column changed type "
                + "incompatibly; regenerate the code or rebuild the data.")
        }
    }

    /// The (element, encoding) pairs the spec defines. Integers take the integer
    /// encodings, strings the dictionary ones, and an array takes the composition that
    /// applies all of those to its elements.
    private static func encodingSupported(_ column: Column) -> Bool {
        if column.encoding == encodingRaw { return true }

        // An array's block says what its elements use, and the element encoding is checked
        // as it is read rather than here - the descriptor carries only the outer one, so
        // this is as far as the descriptor can be checked.
        if column.kind != kindScalar { return column.encoding == encodingArray }

        switch column.element {
        case elementBool, elementVarint:
            return column.encoding == encodingRle || column.encoding == encodingBitpack

        case elementI32:
            return (column.encoding >= encodingVarint && column.encoding <= encodingDeltaRle)
                || column.encoding == encodingBitpack

        // The dictionary is parameterized by element, so this reaches it with entries that
        // are simply their own raw bytes.
        case elementI64:
            return column.encoding == encodingDict || column.encoding == encodingDictRle
                || column.encoding == encodingBitpack

        // A float column additionally reaches the integer encodings, through the block
        // that says its values are whole numbers.
        case elementF32, elementF64:
            return column.encoding == encodingDict || column.encoding == encodingDictRle
                || column.encoding == encodingWhole

        // And a string dictionary can be front coded or built from segments, both of which
        // are meaningless for a fixed-width element and refused for one.
        case elementString:
            return (column.encoding >= encodingDict
                    && column.encoding <= encodingDictFrontRle)
                || column.encoding == encodingDictSegment
                || column.encoding == encodingDictSegmentRle

        default:
            return false
        }
    }

    /// That a block was consumed exactly: a mismatch is a format disagreement, and
    /// stopping here names the column instead of corrupting the next.
    public static func checkBlockEnd(
        _ reader: Reader, _ column: Column, _ expectedEnd: Int
    ) throws {
        if reader.position != expectedEnd {
            throw TcbError(
                "column tag \(column.tag): its block declared \(column.byteLength) bytes "
                + "but the read ended \(expectedEnd - reader.position) bytes short of its "
                + "boundary")
        }
    }

    /// Reads a whole file into memory.
    public static func readAllBytes(_ filename: String) throws -> [UInt8] {
        guard let data = FileManager.default.contents(atPath: filename) else {
            throw TcbError("could not read \(filename)")
        }

        return [UInt8](data)
    }
}
